description:
Implement a `usePrevious` hook that returns the value from the **previous** render. On the first render it returns `undefined`.

**Example:**
```tsx
const prev = usePrevious(count);
// first render: undefined
// after count changes from 0 → 1: prev is 0
```

starter_code:
import { useEffect, useRef } from 'react';

export function usePrevious<T>(value: T): T | undefined {
  // your code here
}

test_suite:
test('returns undefined on first render', () => {
  const { result } = renderHook(() => usePrevious(42));
  expect(result.current).toBeUndefined();
});

test('returns previous value after rerender', () => {
  const { result, rerender } = renderHook(({ v }) => usePrevious(v), { initialProps: { v: 1 } });
  rerender({ v: 2 });
  expect(result.current).toBe(1);
});

test('updates correctly over multiple rerenders', () => {
  const { result, rerender } = renderHook(({ v }) => usePrevious(v), { initialProps: { v: 'a' } });
  rerender({ v: 'b' });
  rerender({ v: 'c' });
  expect(result.current).toBe('b');
});

// __hidden__
test('works with object values', () => {
  const obj1 = { x: 1 };
  const obj2 = { x: 2 };
  const { result, rerender } = renderHook(({ v }) => usePrevious(v), { initialProps: { v: obj1 } });
  rerender({ v: obj2 });
  expect(result.current).toBe(obj1);
});

solution:
import { useEffect, useRef } from 'react';

export function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T | undefined>(undefined);
  useEffect(() => {
    ref.current = value;
  });
  return ref.current;
}
